function CatHouseMatchSuccessPopup:__init()
    self.pngWriter = nil
    self.captureGo = nil
    self.captureCamera = nil
end

function CatHouseMatchSuccessPopup:__delete()
    if not isNull(self.pngWriter) then
        self.pngWriter.onComplete = nil
        self.pngWriter = nil
    end
    self.captureCamera = nil
    if not isNull(self.captureGo) then
        KTool.SafeDelete(self.captureGo, true)
