function CatHouseMatchSuccessPopup:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if isNull(self.captureGo) then
            local modelLoader = ResourceModule.LoadBundleAsync(CapturePrefabPath, nil, true)
            while not modelLoader.IsCompleted do
                cs_coroutine.yield_return(Yielders.EndOfFrame)
            end
            if not isNull(modelLoader.ResultObject) then
                local modelIns = modelLoader:Instantiate()
                modelLoader:Release()
                modelIns.name = "CAPTURE_EGG_SCREEN"
                self.captureGo = modelIns
                self.pngWriter = modelIns:GetComponentInChildren(typeof(AutoPNGWriter), true)
                if not isNull(self.pngWriter) then
                    self.pngWriter.onComplete = function(id, path)
                        --print(id, path)
                        Events.Broadcast(CatHouseCaptureTextureComplete, id, path)
                    end
                end
                self.captureCamera = modelIns.transform:Find(CaptureCameraName).gameObject
            else
                modelLoader:Release()
                return
            end
        end
        CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_peidui)
        self:LoadEgg()
        self.__EventTimeChangeAction = Events.AddListener(CatHouseTimeChange, Bind(self, self.OnEventTimeChangeAction))
    end))
    return coWait
end

function CatHouseMatchSuccessPopup:OnHide()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self.captureGo then
            KTool.SafeDelete(self.captureGo.gameObject, true)
        end
        self.captureGo = nil
    end))
    return coWait
end

