function CatHouseMatchSuccessPopup:LoadEgg()
    if isNull(self.pngWriter) then
        return
    end

    local parent = self.captureCamera
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local catData = component:GetCatDataById(self.catId)
    ---@type CatHouseCatVo
    local catHouseCatVo = CfUtils.GetCfVo(AutoIds.IdSetting1906, "CatHouseCatVo", catData.catId)
    local assetPath = string.format("Arts/Prefab_cat/Prefab_catparts/%s.prefab", catHouseCatVo.catEgg)
    local go = GameUtils.LoadBundleAsync(assetPath, parent.gameObject, false, true)
    --local go, loader = GameUtils.LoadBundleAsync("Arts/Prefab_cat/100_egg01.prefab", parent.gameObject, false, true)
    if isNull(go) then
        return
    end
    go.transform.localPosition = Vector3.New(0.01, -0.03, 2.24)
    go.transform.localRotation = Quaternion.Euler(0, 180, -3)
    KTool.SetLayer(parent.gameObject, go.gameObject, true);

    local captureCamera = self.pngWriter.gameObject:GetComponentInChildren(CameraType)
    local targetTexture = captureCamera.targetTexture
    self.CatEggImage.texture = targetTexture

end

function CatHouseMatchSuccessPopup:RemoveCDEvent()
    if self.__EventTimeChangeAction then
        Events.RemoveListener(CatHouseTimeChange, self.__EventTimeChangeAction)
        self.__EventTimeChangeAction = nil
    end
end

