function CatHouseMatchSuccessPopup:OnEventTimeChangeAction()
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local cdData = component:GetCDDataById(self.catId)
    if cdData == nil or next(cdData) == nil or cdData[Hatching] == nil then
        return
    end
    self.TextTime.text = GetTimeHMS2(cdData[Hatching])
end

